import { Hono } from "hono";

import { createApi } from "@acme/api";

/**
 * Worker entry point. `Env` comes from worker-configuration.d.ts, generated by
 * `bun run typegen`. Re-run typegen after changing wrangler.jsonc and commit it.
 */
const app = new Hono<{ Bindings: Env }>();

app.route("/api", createApi());

export default {
  async fetch(_request, _env, _ctx): Promise<Response> {
    return app.fetch(_request, _env, _ctx);
  },
} satisfies ExportedHandler<Env>;
